// Concepts: Int[] readings, reduction helpers (sum/min/max), real mean, second pass counting values above the mean, fx summary block
// expect: count: 10
// expect: sum: 641
// expect: min: 23
// expect: max: 87
// expect: mean: 64.10
// expect: above mean: 6

fn sumOf(xs: Int[]) -> Int {
    let total: Int = 0;
    loop i in 0..length(xs) { total = total + xs[i]; }
    ret total;
}

fn minOf(xs: Int[]) -> Int {
    let m: Int = xs[0];
    loop i in 0..length(xs) { if xs[i] < m { m = xs[i]; } }
    ret m;
}

fn maxOf(xs: Int[]) -> Int {
    let m: Int = xs[0];
    loop i in 0..length(xs) { if xs[i] > m { m = xs[i]; } }
    ret m;
}

fn main() -> Void {
    let xs: Int[] = [59, 76, 73, 86, 76, 69, 87, 23, 61, 31];
    let n: Int = length(xs);
    let total: Int = sumOf(xs);
    let lo: Int = minOf(xs);
    let hi: Int = maxOf(xs);
    let mean: Real = total * 1.0 / n;
    let above: Int = 0;
    loop i in 0..n { if xs[i] * 1.0 > mean { above = above + 1; } }
    fx {
        println("count: ", n);
        println("sum: ", total);
        println("min: ", lo);
        println("max: ", hi);
        println("mean: ", mean:0:2);
        println("above mean: ", above);
    }
    ret;
}

