// expect: sorted[6] = 72
// expect: sorted[7] = 80
// expect: sorted[8] = 93
// expect: min: 7
// expect: max: 93

fn insertionSort(xs: Int[]) -> Int[] {
    let n: Int = length(xs);
    loop i in 1..n {
        let key: Int = xs[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if xs[j] <= key { break; }
            xs[j + 1] = xs[j];
            j = j - 1;
        }
        xs[j + 1] = key;
    }
    ret xs;
}

fn selectionSort(xs: Int[]) -> Int[] {
    let n: Int = length(xs);
    loop i in 0..n {
        let m: Int = i;
        loop j in i + 1..n { if xs[j] < xs[m] { m = j; } }
        let tmp: Int = xs[i];
        xs[i] = xs[m];
        xs[m] = tmp;
    }
    ret xs;
}

fn joinInts(xs: Int[]) -> Text {
    let out: Text = "";
    let n: Int = length(xs);
    loop i in 0..n { if i > 0 { out = out + " "; } out = out + int_to_text(xs[i]); }
    ret out;
}

fn main() -> Void {
    let xs: Int[] = [46, 7, 80, 93, 41, 10, 45, 72, 55];
    let algo: Text = "insertion";
