fn bubble_sort(xs: Int[]) -> Int[] {
    let result: Int[] = xs;
    let n: Int = length(result);
    let swapped: Bool = true;
    loop while swapped {
        swapped = false;
        loop i in 0..n - 1 {
            if result[i] > result[i + 1] {
                let temp: Int = result[i];
                result[i] = result[i + 1];
                result[i + 1] = temp;
                swapped = true;
            }
        }
    }
    ret result;
}

