type Stack {
    items: Int[];

    fn push(val: Int) -> Void {
        self.items = self.items + [val];
        ret;
    }

    fn pop() -> Int {
        let top: Int = self.items[length(self.items) - 1];
        let newItems: Int[] = [];
        loop i in 0..length(self.items) - 1 { newItems = newItems + [self.items[i]]; }
        self.items = newItems;
        ret top;
    }

    fn peek() -> Int {
        ret self.items[length(self.items) - 1];
    }

    fn size() -> Int {
        ret length(self.items);
    }
}

@pure
fn isOp(ch: Text) -> Bool {
    if ch == "+" { ret true; }
    if ch == "-" { ret true; }
    if ch == "*" { ret true; }
    if ch == "/" { ret true; }
    ret false;
}

fn evalRPN(tokens: Text[]) -> Int {
    let stack: Stack = new Stack { items: [] };

    loop i in 0..length(tokens) {
        let tok: Text = tokens[i];
        if isOp(tok) {
            let b: Int = stack.pop();
            let a: Int = stack.pop();
            let result: Int = 0;
            if tok == "+" { result = a + b; }
            if tok == "-" { result = a - b; }
            if tok == "*" { result = a * b; }
            if tok == "/" { result = a / b; }
            stack.push(result);
        } else {
            stack.push(parse_int(tok));
        }
    }
    ret stack.pop();
}

fn main() -> Void {
    let expr1: Text[] = ["2", "3", "+", "4", "*"];
    let expr2: Text[] = ["5", "1", "2", "+", "4", "*", "+", "3", "-"];

    fx {
        println("Expression: 2 3 + 4 * => ", evalRPN(expr1));
        println("Expression: 5 1 2 + 4 * + 3 - => ", evalRPN(expr2));
    }
    ret;
}

type Grid {
    width: Int;
    height: Int;
    cells: Int[];

    fn idx(r: Int, c: Int) -> Int {
        ret r * self.width + c;
    }

    fn alive(r: Int, c: Int) -> Bool {
        if r < 0 || r >= self.height || c < 0 || c >= self.width { ret false; }
        ret self.cells[self.idx(r, c)] == 1;
    }

    fn countNeighbors(r: Int, c: Int) -> Int {
        let count: Int = 0;
        let dr: Int = -1;
        loop dr <= 1 {
            let dc: Int = -1;
            loop dc <= 1 {
                if dr != 0 || dc != 0 {
                    if self.alive(r + dr, c + dc) { count = count + 1; }
                }
                dc = dc + 1;
            }
            dr = dr + 1;
        }
        ret count;
    }

    fn step() -> Grid {
        let next: Int[] = [];
        loop i in 0..self.width * self.height { next = next + [0]; }
        let result: Grid = new Grid { width: self.width, height: self.height, cells: next };

        loop r in 0..self.height {
            loop c in 0..self.width {
                let n: Int = self.countNeighbors(r, c);
                let current: Int = self.cells[self.idx(r, c)];
                if current == 1 && (n == 2 || n == 3) {
                    result.cells[result.idx(r, c)] = 1;
                }
                if current == 0 && n == 3 { result.cells[result.idx(r, c)] = 1; }
            }
        }
        ret result;
    }

    fn display() -> Void {
        loop r in 0..self.height {
            let line: Text = "";
            loop c in 0..self.width {
                if self.alive(r, c) {
                    line = line + "# ";
                } else {
                    line = line + ". ";
                }
            }
            fx { println(line); }
        }
        ret;
    }
}

fn main() -> Void {
    let w: Int = 10;
    let h: Int = 6;
    let cells: Int[] = [];
    loop i in 0..w * h { cells = cells + [0]; }
    let grid: Grid = new Grid { width: w, height: h, cells: cells };

    grid.cells[grid.idx(1, 2)] = 1;
    grid.cells[grid.idx(2, 3)] = 1;
    grid.cells[grid.idx(3, 1)] = 1;
    grid.cells[grid.idx(3, 2)] = 1;
    grid.cells[grid.idx(3, 3)] = 1;

    let generations: Int = 5;
    loop gen in 0..generations {
        fx { println("--- Generation ", gen, " ---"); }
        grid.display();
        grid = grid.step();
    }
    fx { println("--- Final ---"); }
    grid.display();
    ret;
}

// Line/word/char counter over an in-memory Text[] of lines. Aether exposes
// no readable "file variable" type from its own syntax (assign/reset/readln
// are real vm_builtins, but "First arg to Assign must be a file variable"
// -- there is no Aether-level file-content-read API), so this demonstrates
// the counting logic directly rather than pretending to open a real file.
fn main() -> Void {
    let lines: Text[] = [
        "the quick brown fox",
        "jumps over the lazy dog",
        "aether is a compact language"
    ];

    let lineCount: Int = 0;
    let wordCount: Int = 0;
    let charCount: Int = 0;

    loop li in 0..length(lines) {
        let line: Text = lines[li];
        lineCount = lineCount + 1;
        charCount = charCount + string_len(line);

        let words: Text[] = split(line, " ");
        loop wi in 0..length(words) {
            if string_len(words[wi]) > 0 { wordCount = wordCount + 1; }
        }
    }

    fx {
        println("Lines: ", lineCount);
        println("Words: ", wordCount);
        println("Chars: ", charCount);
    }
    ret;
}

type Account {
    id: Int;
    owner: Text;
    balance: Real;

    fn deposit(amount: Real) -> Bool {
        if amount <= 0.0 { ret false; }
        self.balance = self.balance + amount;
        ret true;
    }

    fn withdraw(amount: Real) -> Bool {
        if amount <= 0.0 || amount > self.balance { ret false; }
        self.balance = self.balance - amount;
        ret true;
    }

    fn transfer(to: Account, amount: Real) -> Bool {
        if !self.withdraw(amount) { ret false; }
        if !to.deposit(amount) { self.deposit(amount); ret false; }
        ret true;
    }

    fn print() -> Void {
        fx {
            println("Account ", self.id, " (", self.owner, "): ", formatfloat(self.balance, 2));
        }
        ret;
    }
}

fn main() -> Void {
    let alice: Account = new Account { id: 1, owner: "Alice", balance: 1000.0 };
    let bob: Account = new Account { id: 2, owner: "Bob", balance: 500.0 };

    alice.print();
    bob.print();

    alice.deposit(200.0);
    bob.withdraw(100.0);

    alice.transfer(bob, 300.0);

    alice.print();
    bob.print();
    ret;
}

@pure
fn isLeapYear(year: Int) -> Bool {
    if year % 400 == 0 { ret true; }
    if year % 100 == 0 { ret false; }
    if year % 4 == 0 { ret true; }
    ret false;
}

@pure
fn daysInMonth(year: Int, month: Int) -> Int {
    if month == 2 { if isLeapYear(year) { ret 29; } ret 28; }
    if month == 4 || month == 6 || month == 9 || month == 11 { ret 30; }
    ret 31;
}

@pure
fn dayOfYear(year: Int, month: Int, day: Int) -> Int {
    let total: Int = 0;
    loop m in 1..month + 1 {
        if m < month {
            total = total + daysInMonth(year, m);
        } else {
            total = total + day;
        }
    }
    ret total;
}

@pure
fn addDays(year: Int, month: Int, day: Int, days: Int) -> Text {
    let d: Int = day + days;
    let m: Int = month;
    let y: Int = year;
    loop d > daysInMonth(y, m) {
        d = d - daysInMonth(y, m);
        m = m + 1;
        if m > 12 { m = 1; y = y + 1; }
    }
    ret itoa(y) + "-" + itoa(m) + "-" + itoa(d);
}

fn main() -> Void {
    let year: Int = 2024;
    let month: Int = 3;
    let day: Int = 15;

    fx {
        println("Date: ", year, "-", month, "-", day);
        println("Day of year: ", dayOfYear(year, month, day));
        println("100 days later: ", addDays(year, month, day, 100));
        println("Is 2024 leap? ", isLeapYear(2024));
    }
    ret;
}

type HashEntry {
    key: Text;
    value: Text;
    next: HashEntry;
}

fn makeHashEntry(k: Text, v: Text) -> HashEntry {
    ret new HashEntry { key: k, value: v, next: nil };
}

type HashMap {
    buckets: HashEntry[];
    capacity: Int;

    fn hash(key: Text) -> Int {
        let h: Int = 0;
        let len: Int = string_len(key);
        loop i in 0..len { h = h * 31 + ord(copy(key, i + 1, 1)); }
        if h < 0 { h = -h; }
        ret h % self.capacity;
    }

    fn put(key: Text, value: Text) -> Void {
        let idx: Int = self.hash(key);
        let entry: HashEntry = self.buckets[idx];
        loop entry != nil {
            if entry.key == key { entry.value = value; ret; }
            entry = entry.next;
        }
        let newEntry: HashEntry = makeHashEntry(key, value);
        newEntry.next = self.buckets[idx];
        self.buckets[idx] = newEntry;
        ret;
    }

    fn get(key: Text) -> Text {
        let idx: Int = self.hash(key);
        let entry: HashEntry = self.buckets[idx];
        loop entry != nil { if entry.key == key { ret entry.value; } entry = entry.next; }
        ret "";
    }

    fn contains(key: Text) -> Bool {
        ret self.get(key) != "";
    }
}

fn makeHashMap(cap: Int) -> HashMap {
    let buckets: HashEntry[] = [];
    loop i in 0..cap { buckets = buckets + [nil]; }
    ret new HashMap { buckets: buckets, capacity: cap };
}

fn main() -> Void {
    let map: HashMap = makeHashMap(16);

    map.put("name", "Alice");
    map.put("city", "Wonderland");
    map.put("age", "30");

    fx {
        println("name: ", map.get("name"));
        println("city: ", map.get("city"));
        println("contains 'age'? ", map.contains("age"));
        println("contains 'email'? ", map.contains("email"));
    }
    ret;
}

type TreeNode {
    value: Int;
    left: TreeNode;
    right: TreeNode;
}

fn makeTreeNode(val: Int) -> TreeNode {
    ret new TreeNode { value: val, left: nil, right: nil };
}

fn insert(root: TreeNode, val: Int) -> TreeNode {
    if root == nil { ret makeTreeNode(val); }
    if val < root.value {
        root.left = insert(root.left, val);
    } else {
        root.right = insert(root.right, val);
    }
    ret root;
}

fn inorder(root: TreeNode) -> Text {
    if root == nil { ret ""; }
    let result: Text = inorder(root.left);
    result = result + itoa(root.value) + " ";
    result = result + inorder(root.right);
    ret result;
}

fn preorder(root: TreeNode) -> Text {
    if root == nil { ret ""; }
    let result: Text = itoa(root.value) + " ";
    result = result + preorder(root.left);
    result = result + preorder(root.right);
    ret result;
}

fn postorder(root: TreeNode) -> Text {
    if root == nil { ret ""; }
    let result: Text = postorder(root.left);
    result = result + postorder(root.right);
    result = result + itoa(root.value) + " ";
    ret result;
}

fn main() -> Void {
    let root: TreeNode = nil;
    root = insert(root, 50);
    root = insert(root, 30);
    root = insert(root, 70);
    root = insert(root, 20);
    root = insert(root, 40);
    root = insert(root, 60);
    root = insert(root, 80);

    fx {
        println("Inorder:   ", inorder(root));
        println("Preorder:  ", preorder(root));
        println("Postorder: ", postorder(root));
    }
    ret;
}

@pure
fn is_prime(n: Int) -> Bool {
    if n <= 1 { ret false; }
    if n == 2 { ret true; }
    if n % 2 == 0 { ret false; }
    let max: Int = int(sqrt(real(n)));
    let i: Int = 3;
    loop i <= max { if n % i == 0 { ret false; } i = i + 2; }
    ret true;
}

fn generate_primes(limit: Int) -> Int[] {
    let primes: Int[] = [];
    loop i in 2..limit { if is_prime(i) { primes = primes + [i]; } }
    ret primes;
}

fn main() -> Void {
    let limit: Int = 50;
    let primes: Int[] = generate_primes(limit);
    fx {
        print("Primes up to ", limit, ": ");
        loop i in 0..length(primes) { print(primes[i], " "); }
        println("");
    }
    ret;
}

type Json {
    kind: Text;  // "object", "array", "string", "number", "bool", "null"
    value: Text;
    children: Json[];
}

@pure
fn is_digit(ch: Text) -> Bool {
    let code: Int = ord(ch);
    ret code >= 48 && code <= 57;
}

@pure
fn is_number(text: Text) -> Bool {
    loop i in 0..string_len(text) {
        let c: Text = copy(text, i + 1, 1);
        if !is_digit(c) && c != "." && c != "-" { ret false; }
    }
    ret true;
}

fn parse_json(text: Text) -> Json {
    if text == "null" { ret new Json { kind: "null", value: "null", children: [] }; }
    if text == "true" || text == "false" {
        ret new Json { kind: "bool", value: text, children: [] };
    }
    if is_number(text) { ret new Json { kind: "number", value: text, children: [] }; }
    let len: Int = string_len(text);
    if len >= 2 && copy(text, 1, 1) == "\"" && copy(text, len, 1) == "\"" {
        ret new Json { kind: "string", value: copy(text, 2, len - 2), children: [] };
    }
    ret new Json { kind: "unknown", value: "", children: [] };
}

fn main() -> Void {
    let json_text: Text = "\"Alice\"";
    let json: Json = parse_json(json_text);
    fx {
        println("Parsed JSON kind: ", json.kind);
        println("Parsed JSON value: ", json.value);
    }
    ret;
}

// Grayscale conversion over an in-memory Image. Aether's real file I/O
// (assign/reset/rewrite/readln/writeln) is text-line-oriented, not
// byte-level, so there is no way to parse a binary BMP file from Aether
// source -- this demonstrates the pixel-transform logic on synthetic data
// instead of pretending to load/save a real image file.
type Pixel {
    r: Int;
    g: Int;
    b: Int;
}

type Image {
    width: Int;
    height: Int;
    pixels: Pixel[];
}

fn make_test_image(width: Int, height: Int) -> Image {
    let pixels: Pixel[] = [];
    loop i in 0..width * height {
        pixels = pixels + [new Pixel { r: (i * 37) % 256, g: (i * 59) % 256, b: (i * 83) % 256 }];
    }
    ret new Image { width: width, height: height, pixels: pixels };
}

fn grayscale(image: Image) -> Image {
    let gray_pixels: Pixel[] = [];
    loop i in 0..length(image.pixels) {
        let p: Pixel = image.pixels[i];
        let gray: Int = int(0.299 * real(p.r) + 0.587 * real(p.g) + 0.114 * real(p.b));
        gray_pixels = gray_pixels + [new Pixel { r: gray, g: gray, b: gray }];
    }
    ret new Image { width: image.width, height: image.height, pixels: gray_pixels };
}

fn main() -> Void {
    let image: Image = make_test_image(2, 2);
    let gray: Image = grayscale(image);
    fx {
        loop i in 0..length(gray.pixels) {
            let p: Pixel = gray.pixels[i];
            println("pixel ", i, ": r=", p.r, " g=", p.g, " b=", p.b);
        }
    }
    ret;
}

type DB {
    data: Text[];
}

fn open_store(filename: Text) -> DB {
    let data: Text[] = [];
    fx {
        if fileexists(filename) {
            let f: File;
            assign(f, filename);
            reset(f);
            loop {
                if eof(f) { break; }
                let line: Text;
                readln(f, line);
                if string_len(line) > 0 { data = data + [line]; }
            }
            close(f);
        }
    }
    ret new DB { data: data };
}

fn put_entry(db: DB, key: Text, value: Text) -> Void {
    let index: Int = -1;
    let i: Int = 0;
    loop i < length(db.data) { if db.data[i] == key { index = i; break; } i = i + 2; }
    if index != -1 {
        db.data[index + 1] = value;
    } else {
        db.data = db.data + [key];
        db.data = db.data + [value];
    }
    ret;
}

fn get_entry(db: DB, key: Text) -> Text {
    let i: Int = 0;
    loop i < length(db.data) { if db.data[i] == key { ret db.data[i + 1]; } i = i + 2; }
    ret "";
}

fn save_store(db: DB, filename: Text) -> Void {
    fx {
        let f: File;
        assign(f, filename);
        rewrite(f);
        loop i in 0..length(db.data) { writeln(f, db.data[i]); }
        close(f);
    }
    ret;
}

fn main() -> Void {
    let db: DB = open_store("/tmp/aether_db_demo.txt");
    put_entry(db, "name", "Alice");
    put_entry(db, "age", "30");
    fx {
        println("Name: ", get_entry(db, "name"));
        println("Age: ", get_entry(db, "age"));
    }
    save_store(db, "/tmp/aether_db_demo.txt");
    ret;
}

@pure
fn vigenere_encrypt(text: Text, key: Text) -> Text {
    let result: Text = "";
    let key_len: Int = string_len(key);
    loop i in 0..string_len(text) {
        let c: Int = ord(copy(text, i + 1, 1));
        let k: Int = ord(copy(key, (i % key_len) + 1, 1));
        let encrypted: Int = (c + k - 2 * 97) % 26 + 97;
        result = result + chr(encrypted);
    }
    ret result;
}

@pure
fn vigenere_decrypt(text: Text, key: Text) -> Text {
    let result: Text = "";
    let key_len: Int = string_len(key);
    loop i in 0..string_len(text) {
        let c: Int = ord(copy(text, i + 1, 1));
        let k: Int = ord(copy(key, (i % key_len) + 1, 1));
        let decrypted: Int = (c - k + 26) % 26 + 97;
        result = result + chr(decrypted);
    }
    ret result;
}

fn main() -> Void {
    let plaintext: Text = "hello";
    let key: Text = "secret";
    let ciphertext: Text = vigenere_encrypt(plaintext, key);
    let decrypted: Text = vigenere_decrypt(ciphertext, key);
    fx {
        println("Original: ", plaintext);
        println("Encrypted: ", ciphertext);
        println("Decrypted: ", decrypted);
    }
    ret;
}

// Markov chain over word transitions. Aether has no generic Map<K,V> type
// (no generics at all) and no .contains()/.put()/.get() method-call sugar,
// so transitions are modeled as a linear array of (key, nexts) records
// instead, matching the plain-array idiom used elsewhere in this corpus.
type Transition {
    key: Text;
    nexts: Text[];
}

type MarkovChain {
    transitions: Transition[];
}

fn find_transition(chain: MarkovChain, key: Text) -> Int {
    loop i in 0..length(chain.transitions) {
        if chain.transitions[i].key == key {
            ret i;
        }
    }
    ret -1;
}

fn train(chain: MarkovChain, text: Text) -> Void {
    let words: Text[] = split(text, " ");
    loop i in 0..length(words) - 1 {
        let key: Text = words[i];
        let next: Text = words[i + 1];
        let idx: Int = find_transition(chain, key);
        if idx == -1 {
            chain.transitions = chain.transitions + [new Transition { key: key, nexts: [next] }];
        } else {
            chain.transitions[idx].nexts = chain.transitions[idx].nexts + [next];
        }
    }
    ret;
}

fn generate(chain: MarkovChain, start: Text, length_limit: Int) -> Text {
    let result: Text = start;
    let current: Text = start;
    loop i in 0..length_limit {
        let idx: Int = find_transition(chain, current);
        if idx == -1 {
            break;
        }
        let next_words: Text[] = chain.transitions[idx].nexts;
        let pick: Int = 0;
        fx { pick = random(length(next_words)); }
        current = next_words[pick];
        result = result + " " + current;
    }
    ret result;
}

fn main() -> Void {
    let chain: MarkovChain = new MarkovChain { transitions: [] };
    let text: Text = "the cat sat on the mat the dog sat on the log";
    train(chain, text);

    let generated: Text = "";
    fx {
        randomize();
        generated = generate(chain, "the", 10);
        println("Generated: ", generated);
    }
    ret;
}

// Genetic algorithm searching for a target Int[] pattern. Aether has no
// lambdas/function-values (FUNC-001) and no generic sort() builtin, so
// selection is done with a hand-written descending-fitness selection sort
// instead of sort(population, (a,b) -> ...). random(n) needs its own fx
// wrap at every call site (fx-ness is not inherited through calls).
type Individual {
    genes: Int[];
    fitness: Real;
}

fn random_individual(length: Int) -> Individual {
    let genes: Int[] = [];
    fx {
        loop i in 0..length {
            genes = genes + [random(100)];
        }
    }
    ret new Individual { genes: genes, fitness: 0.0 };
}

fn calculate_fitness(individual: Individual, target: Int[]) -> Real {
    let sum: Real = 0.0;
    loop i in 0..length(individual.genes) {
        sum = sum + abs(real(individual.genes[i] - target[i]));
    }
    individual.fitness = 1.0 / (1.0 + sum);
    ret individual.fitness;
}

fn crossover(parent1: Individual, parent2: Individual) -> Individual {
    let child: Int[] = [];
    let midpoint: Int = 0;
    fx {
        midpoint = random(length(parent1.genes));
    }
    loop i in 0..midpoint {
        child = child + [parent1.genes[i]];
    }
    loop i in midpoint..length(parent2.genes) {
        child = child + [parent2.genes[i]];
    }
    ret new Individual { genes: child, fitness: 0.0 };
}

fn mutate(individual: Individual, mutation_rate: Real) -> Void {
    fx {
        loop i in 0..length(individual.genes) {
            if random() < mutation_rate {
                individual.genes[i] = random(100);
            }
        }
    }
    ret;
}

fn sort_by_fitness_desc(population: Individual[]) -> Void {
    let n: Int = length(population);
    loop i in 0..n {
        let best: Int = i;
        loop j in i + 1..n {
            if population[j].fitness > population[best].fitness {
                best = j;
            }
        }
        if best != i {
            let tmp: Individual = population[i];
            population[i] = population[best];
            population[best] = tmp;
        }
    }
    ret;
}

fn genetic_algorithm(target: Int[]) -> Individual {
    let population: Individual[] = [];
    loop i in 0..10 {
        population = population + [random_individual(length(target))];
    }

    loop generation in 0..100 {
        loop i in 0..length(population) {
            calculate_fitness(population[i], target);
        }
        sort_by_fitness_desc(population);

        let new_population: Individual[] = [];
        loop i in 0..5 {
            let p1: Int = 0;
            let p2: Int = 0;
            fx {
                p1 = random(5);
                p2 = random(5);
            }
            let parent1: Individual = population[p1];
            let parent2: Individual = population[p2];
            let child: Individual = crossover(parent1, parent2);
            mutate(child, 0.01);
            new_population = new_population + [child];
        }
        population = new_population;
    }

    ret population[0];
}

fn main() -> Void {
    let target: Int[] = [50, 50, 50];
    fx { randomize(); }
    let solution: Individual = genetic_algorithm(target);
    fx {
        print("Solution: ");
        loop i in 0..length(solution.genes) {
            print(solution.genes[i], " ");
        }
        println("");
    }
    ret;
}

type Neuron {
    weights: Real[];
    bias: Real;
}

type Layer {
    neurons: Neuron[];
}

type Network {
    layers: Layer[];
}

@pure
fn sigmoid(x: Real) -> Real {
    ret 1.0 / (1.0 + exp(-x));
}

fn forward(network: Network, input: Real[]) -> Real[] {
    let output: Real[] = input;
    loop l in 0..length(network.layers) {
        let layer: Layer = network.layers[l];
        let new_output: Real[] = [];
        loop n in 0..length(layer.neurons) {
            let neuron: Neuron = layer.neurons[n];
            let sum: Real = 0.0;
            loop i in 0..length(output) { sum = sum + output[i] * neuron.weights[i]; }
            sum = sum + neuron.bias;
            new_output = new_output + [sigmoid(sum)];
        }
        output = new_output;
    }
    ret output;
}

fn main() -> Void {
    let network: Network = new Network { layers: [
        new Layer { neurons: [
            new Neuron { weights: [0.5, -0.5], bias: 0.1 },
            new Neuron { weights: [0.3, 0.7], bias: -0.2 }
        ]}
    ]};
    let input: Real[] = [1.0, 2.0];
    let output: Real[] = forward(network, input);
    fx {
        print("Output: ");
        loop i in 0..length(output) { print(output[i]:0:4, " "); }
        println("");
    }
    ret;
}

type Grid {
    width: Int;
    height: Int;
    cells: Bool[];
}

fn create_grid(width: Int, height: Int) -> Grid {
    let cells: Bool[] = [];
    fx {
        loop y in 0..height {
            loop x in 0..width {
                cells = cells + [random() > 0.7];
            }
        }
    }
    ret new Grid { width: width, height: height, cells: cells };
}

fn count_neighbors(grid: Grid, x: Int, y: Int) -> Int {
    let count: Int = 0;
    loop dy in -1..2 {
        loop dx in -1..2 {
            if dx == 0 && dy == 0 {
                continue;
            }
            let nx: Int = x + dx;
            let ny: Int = y + dy;
            if nx >= 0 && nx < grid.width && ny >= 0 && ny < grid.height {
                let index: Int = ny * grid.width + nx;
                if grid.cells[index] {
                    count = count + 1;
                }
            }
        }
    }
    ret count;
}

fn next_generation(grid: Grid) -> Grid {
    let new_cells: Bool[] = [];
    loop y in 0..grid.height {
        loop x in 0..grid.width {
            let index: Int = y * grid.width + x;
            let neighbors: Int = count_neighbors(grid, x, y);
            if grid.cells[index] {
                new_cells = new_cells + [neighbors == 2 || neighbors == 3];
            } else {
                new_cells = new_cells + [neighbors == 3];
            }
        }
    }
    ret new Grid { width: grid.width, height: grid.height, cells: new_cells };
}

fn print_grid(grid: Grid) -> Void {
    fx {
        loop y in 0..grid.height {
            let row: Text = "";
            loop x in 0..grid.width {
                let index: Int = y * grid.width + x;
                row = row + (if grid.cells[index] { "X" } else { "." });
            }
            println(row);
        }
    }
