fn insertion_sort(arr: Int[]) -> Void {
    let n: Int = length(arr);
    loop i in 1..n {
        let key: Int = arr[i];
        let j: Int = i - 1;
        loop {
            if !(j >= 0 && arr[j] > key) { break; }
            arr[j + 1] = arr[j];
            j = j - 1;
        }
        arr[j + 1] = key;
    }
    ret;
}

