@pure
@pre a > 0
@pre b > 0
@post result > 0
fn gcd(a: Int, b: Int) -> Int {
    let x: Int = a;
    let y: Int = b;

    loop {
        if y == 0 { ret x; }
        let temp: Int = y;
        y = x % y;
        x = temp;
    }

    ret x;
}

@pure
@pre a > 0
@pre b > 0
@post result.0 > 0
@post result.1 > 0
fn gcd_lcm(a: Int, b: Int) -> (Int, Int) {
    let divisor: Int = gcd(a, b);
    let multiple: Int = (a / divisor) * b;
    ret (divisor, multiple);
}

fn main() -> Void {
    let a: Int = 48;
    let b: Int = 18;

    let (d, m) = gcd_lcm(a, b);

    fx {
        println("For ", a, " and ", b, ":");
        println("GCD = ", d);
        println("LCM = ", m);
    }
    ret;
}

type VM {
    stack: Int[];

    fn push(val: Int) -> Void {
        self.stack = self.stack + [val];
        ret;
    }

    fn pop() -> Int {
        let n: Int = length(self.stack);
        if n == 0 { ret 0; }

        let val: Int = self.stack[n - 1];
        let newStack: Int[] = [];

        loop i in 0..(n - 1) { newStack = newStack + [self.stack[i]]; }

        self.stack = newStack;
        ret val;
    }

    fn add() -> Void {
        let b: Int = self.pop();
        let a: Int = self.pop();
        self.push(a + b);
        ret;
    }

    fn multiply() -> Void {
        let b: Int = self.pop();
        let a: Int = self.pop();
        self.push(a * b);
        ret;
    }
}

fn main() -> Void {
    let machine: VM = new VM();

    machine.push(3);
    machine.push(4);
    machine.add();
    machine.push(5);
    machine.multiply();

    let result: Int = machine.pop();

    fx { println("VM Execution Result: ", result); }
    ret;
}

@pure
fn compress(input: Text) -> Text {
    let n: Int = string_len(input);
    if n == 0 { ret ""; }

    let result: Text = "";
    let currentChar: Text = copy(input, 1, 1);
    let count: Int = 1;

    loop i in 1..n {
        let ch: Text = copy(input, i + 1, 1);
        if ch == currentChar {
            count = count + 1;
        } else {
            result = result + currentChar + int_to_text(count);
            currentChar = ch;
            count = 1;
        }
    }

    result = result + currentChar + int_to_text(count);
    ret result;
}

