@pure
@post result >= -1
fn binarySearch(xs: Int[], target: Int) -> Int {
    let lo: Int = 0;
    let hi: Int = length(xs) - 1;
    loop lo <= hi {
        let mid: Int = (lo + hi) / 2;
        if xs[mid] == target { ret mid; }
        if xs[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    ret -1;
}

@pure
fn insertSorted(xs: Int[], v: Int) -> Int[] {
    let result: Int[] = [];
    let inserted: Bool = false;
    loop i in 0..length(xs) {
        if !inserted && xs[i] > v { result = result + [v]; inserted = true; }
        result = result + [xs[i]];
    }
    if !inserted { result = result + [v]; }
    ret result;
}

fn main() -> Void {
    let xs: Int[] = [];
    let values: Int[] = [5, 2, 8, 1, 9, 3, 7, 4, 6];
    loop i in 0..length(values) { xs = insertSorted(xs, values[i]); }
    fx {
        println("Sorted array:");
        loop i in 0..length(xs) { print(xs[i], " "); }
        println("");
    }
    let target: Int = 7;
    let idx: Int = binarySearch(xs, target);
    fx {
        if idx >= 0 {
            println("Found ", target, " at index ", idx);
        } else {
            println(target, " not found");
        }
    }
    ret;
}

@pure
fn collatzLength(n: Int) -> Int {
    let len: Int = 1;
    let current: Int = n;
    loop current > 1 {
        if current % 2 == 0 {
            current = current / 2;
        } else {
            current = 3 * current + 1;
        }
        len = len + 1;
    }
    ret len;
}

fn main() -> Void {
    let limit: Int = 30;
    let lengths: Int[] = [];
    let maxLen: Int = 0;

    loop i in 0..limit {
        let n: Int = i + 1;
        let len: Int = collatzLength(n);
        lengths = lengths + [len];
        if len > maxLen { maxLen = len; }
    }

    fx {
        println("Collatz sequence lengths for n = 1..", limit);
        println("");
        loop i in 0..length(lengths) {
            let n: Int = i + 1;
            let len: Int = lengths[i];
            let bar: Text = stringofchar("#", len);
            println(n, ": ", bar);
        }
        println("");
        println("Longest sequence: ", maxLen, " steps");
    }
    ret;
}

fn sieve(limit: Int) -> Int[] {
    if limit < 2 { ret []; }
    let is_prime: Bool[] = [];
    let i: Int = 0;
    loop i <= limit { is_prime = is_prime + [true]; i = i + 1; }
    is_prime[0] = false;
    is_prime[1] = false;
    let p: Int = 2;
    loop p * p <= limit {
        if is_prime[p] {
            let j: Int = p * p;
            loop j <= limit { is_prime[j] = false; j = j + p; }
        }
        p = p + 1;
    }
    let primes: Int[] = [];
    let k: Int = 2;
    loop k <= limit { if is_prime[k] { primes = primes + [k]; } k = k + 1; }
    ret primes;
}

fn main() -> Void {
    let primes: Int[] = sieve(100);
    let count: Int = length(primes);
    fx { println("Primes up to 100 (", count, " total):"); }
    let i: Int = 0;
    loop i < count { fx { print(primes[i], " "); } i = i + 1; }
    fx { println(""); }
    ret;
}

type CategorySummary {
    name: Text;
    count: Int;
    total: Real;
    minPrice: Real;
    maxPrice: Real;

    fn record(price: Real) -> Void {
        self.count = self.count + 1;
        self.total = self.total + price;
        if price < self.minPrice { self.minPrice = price; }
        if price > self.maxPrice { self.maxPrice = price; }
        ret;
    }

    fn avgPrice() -> Real {
        if self.count == 0 { ret 0.0; }
        ret self.total / self.count;
    }
}

