type VendingMachine {
    balance: Int;
    state: Text;
    dispensed: Text;

    fn insertCoin(amount: Int) -> Void {
        if self.state == "idle" { self.state = "has_balance"; }
        self.balance = self.balance + amount;
        ret;
    }

    fn selectItem(item: Text, cost: Int) -> Text {
        if self.state != "has_balance" { ret "ERROR: insert coins first"; }
        if self.balance < cost { ret "ERROR: insufficient balance"; }
        self.balance = self.balance - cost;
        self.state = "dispensing";
        self.dispensed = item;
        ret "OK";
    }

    fn dispense() -> Text {
        if self.state != "dispensing" { ret "ERROR: no pending dispensation"; }
        let item: Text = self.dispensed;
        self.dispensed = "";
        if self.balance > 0 {
            self.state = "has_balance";
        } else {
            self.state = "idle";
        }
        ret item;
    }

    fn returnChange() -> Int {
        let change: Int = self.balance;
        self.balance = 0;
        self.state = "idle";
        ret change;
    }
}

fn main() -> Void {
    let vm: VendingMachine = new VendingMachine();
    vm.state = "idle";

    fx { println("=== Vending Machine Simulation ==="); }

    fx { println("Insert 50 cents..."); }
    vm.insertCoin(50);

