    fx { println(""); }
    fx { println("Try selecting without coins..."); }
    let r3: Text = vm.selectItem("Candy", 30);
    fx { println(r3); }

    ret;
}

@pre n >= 0
@post result >= 0
@cost 1000 ns
fn fibonacci(n: Int) -> Int {
    if n <= 1 { ret n; }
    let a: Int = 0;
    let b: Int = 1;
    let i: Int = 2;
    loop i <= n {
        let temp: Int = a + b;
        a = b;
        b = temp;
        i = i + 1;
    }
    ret b;
}

@pre n > 0
@post result > 1.0
fn goldenRatioApprox(n: Int) -> Real {
    let fibN: Int = fibonacci(n);
    let fibN1: Int = fibonacci(n - 1);
    let ratio: Real = fibN * 1.0 / fibN1;
    ret ratio;
}

fn main() -> Void {
    fx { println("Fibonacci sequence (first 20 terms):"); }
    let i: Int = 0;
    loop i < 20 { fx { print(fibonacci(i), " "); } i = i + 1; }
    fx { println(""); }
    fx { println(""); }

    fx { println("Golden ratio convergence (fib(n)/fib(n-1)):"); }
    let j: Int = 5;
    loop j <= 25 {
        let ratio: Real = goldenRatioApprox(j);
        fx { println("fib(", j, ")/fib(", j - 1, ") = ", ratio:0:10); }
        j = j + 5;
    }
    fx { println(""); }

    let phi: Real = (1.0 + sqrt(5.0)) / 2.0;
    fx { println("True phi = ", phi:0:10); }

    let finalApprox: Real = goldenRatioApprox(25);
    let error: Real = abs(finalApprox - phi);
    fx { println("Error at n=25: ", error:0:12); }

    ret;
}

type WordEntry {
    wtext: Text;
    count: Int;
}

fn countWords(text: Text) -> WordEntry[] {
    let words: Text[] = split(text, " ");
    let entries: WordEntry[] = [];
    let idx: Int = 0;
    let wcount: Int = length(words);
    loop idx < wcount {
        let w: Text = trim(words[idx]);
        if string_len(w) > 0 {
            let found: Bool = false;
            let j: Int = 0;
            let elen: Int = length(entries);
            loop j < elen {
                if entries[j].wtext == w {
                    entries[j].count = entries[j].count + 1;
                    found = true;
                }
                j = j + 1;
            }
            if !found {
                let entry: WordEntry = new WordEntry();
                entry.wtext = w;
                entry.count = 1;
                entries = entries + [entry];
            }
        }
        idx = idx + 1;
    }
    ret entries;
}

fn sortByCount(entries: WordEntry[]) -> WordEntry[] {
    let n: Int = length(entries);
    let sorted: WordEntry[] = [];
    let k: Int = 0;
    loop k < n { sorted = sorted + [entries[k]]; k = k + 1; }
    let i: Int = 0;
    loop i < n - 1 {
        let maxIdx: Int = i;
        let j: Int = i + 1;
        loop j < n {
            if sorted[j].count > sorted[maxIdx].count { maxIdx = j; }
            j = j + 1;
        }
        if maxIdx != i {
            let tmp: WordEntry = sorted[i];
            sorted[i] = sorted[maxIdx];
            sorted[maxIdx] = tmp;
        }
        i = i + 1;
    }
    ret sorted;
}

fn main() -> Void {
    let sentence: Text = "the cat sat on the mat the cat ate the rat";
    let entries: WordEntry[] = countWords(sentence);
    let sorted: WordEntry[] = sortByCount(entries);
    let n: Int = length(sorted);
    fx { println("Rank | Word       | Count"); println("-----|------------|------"); }
    let i: Int = 0;
    loop i < n {
        let pad: Int = 11 - string_len(sorted[i].wtext);
        if pad < 1 { pad = 1; }
        fx {
            println(i + 1, "    | ", sorted[i].wtext, stringofchar(" ", pad), "| ", sorted[i].count);
        }
        i = i + 1;
    }
    ret;
}

type AgeStats {
    young: Int;   // age < 30
    middle: Int;  // 30 <= age < 60
    senior: Int;  // age >= 60

    fn recordAgeGroup(age: Int) -> Void {
        if age < 30 { self.young = self.young + 1; ret; }
        if age < 60 { // Implies 30 <= age < 60
            self.middle = self.middle + 1;
            ret;
        }
        self.senior = self.senior + 1; // Implies age >= 60
        ret;
    }
}

@pure
@pre age >= 0
fn classifyAge(age: Int) -> Text {
    if age < 30 { ret "Young"; }
    if age < 60 { ret "Middle"; }
    ret "Senior";
}

fn main() -> Void {
    if !has_toon() { fx { println("yyjson unavailable"); } ret; }

    let doc: ToonDoc = toon_parse("[{\"id\": 1, \"age\": 25}, {\"id\": 2, \"age\": 60}, {\"id\": 3, \"age\": 15}, {\"id\": 4, \"age\": 40}, {\"id\": 5, \"age\": 75}]");
    let root: ToonNode = toon_root(doc);

    let stats: AgeStats = new AgeStats();
    let totalUsers: Int = 0;

    loop i in 0..toon_len(root) {
        let userNode: ToonNode = toon_at(root, i);
        let userId: Int = toon_get_int_or(userNode, "id", 0);
        let userAge: Int = toon_get_int_or(userNode, "age", -1); // Use -1 as a sentinel for missing/invalid age

        if userAge >= 0 { // Only process valid ages
            stats.recordAgeGroup(userAge);
            let ageGroup: Text = classifyAge(userAge);
            fx {
                println("User ID: ", userId, ", Age: ", userAge, " -> Group: ", ageGroup);
            }
            totalUsers = totalUsers + 1;
        } else {
            fx { println("Skipping user ID: ", userId, " due to invalid age."); }
        }
        toon_free(userNode); // Free transient node
    }

    fx {
        println("\n--- Age Group Summary ---");
        println("Total Processed Users: ", totalUsers);
        println("Young (<30): ", stats.young);
        println("Middle (30-59): ", stats.middle);
        println("Senior (60+): ", stats.senior);
    }

    toon_close(doc);
    ret;
}

