@pure
@post result.0 <= result.1
fn orderPair(a: Int, b: Int) -> (Int, Int) {
    if a > b {
        ret (b, a);
    }
    ret (a, b);
}

type BoundingBox {
    minX: Int;
    maxX: Int;
    minY: Int;
    maxY: Int;

    fn expand(x: Int, y: Int) -> Void {
        if x < self.minX { self.minX = x; }
        if x > self.maxX { self.maxX = x; }
        if y < self.minY { self.minY = y; }
        if y > self.maxY { self.maxY = y; }
        ret;
    }
}

fn main() -> Void {
    let box: BoundingBox = new BoundingBox();
    box.minX = 1000; box.maxX = -1000;
    box.minY = 1000; box.maxY = -1000;

    let x: Int = 0;
    let y: Int = 0;

    fx { randomize(); }

    loop i in 0..50 {
        box.expand(x, y);

        let step: Int = 0;
        fx { step = random(4); }

        if step == 0 { x = x + 1; }
        if step == 1 { x = x - 1; }
        if step == 2 { y = y + 1; }
        if step == 3 { y = y - 1; }
    }

    let (orderedMinX, orderedMaxX) = orderPair(box.minX, box.maxX);
    let (orderedMinY, orderedMaxY) = orderPair(box.minY, box.maxY);

    fx {
        println("Random walk bounding box after 50 steps:");
        println("X range: [", orderedMinX, ", ", orderedMaxX, "]");
        println("Y range: [", orderedMinY, ", ", orderedMaxY, "]");
    }
    ret;
}

fn sieve(limit: Int) -> Int[] {
    let flags: Bool[] = [];
    let bound: Int = limit + 1;
    loop i in 0..bound { flags = flags + [true]; }
    flags[0] = false;
    if limit >= 1 { flags[1] = false; }
    let i: Int = 2;
    loop i * i <= limit {
        if flags[i] {
            let j: Int = i * i;
            loop j <= limit { flags[j] = false; j = j + i; }
        }
        i = i + 1;
    }
    let primes: Int[] = [];
    loop k in 0..bound { if flags[k] { primes = primes + [k]; } }
    ret primes;
}

fn factorize(n: Int, primes: Int[]) -> Int[] {
    let factors: Int[] = [];
    let remaining: Int = n;
    loop i in 0..length(primes) {
        let p: Int = primes[i];
        if p * p > remaining { break; }
        loop remaining % p == 0 { factors = factors + [p]; remaining = remaining / p; }
    }
    if remaining > 1 { factors = factors + [remaining]; }
    ret factors;
}

fn joinFactors(factors: Int[]) -> Text {
    let result: Text = "";
    loop j in 0..length(factors) {
        if j > 0 { result = result + " * "; }
        result = result + int_to_text(factors[j]);
    }
    ret result;
}

fn main() -> Void {
    let limit: Int = 200;
    let primes: Int[] = sieve(limit);
    fx { println("Primes up to ", limit, ": ", length(primes), " found"); }
    let testNumbers: Int[] = [60, 84, 97, 360, 1024];
    loop i in 0..length(testNumbers) {
        let n: Int = testNumbers[i];
        let factors: Int[] = factorize(n, primes);
        let desc: Text = joinFactors(factors);
        fx { println(n, " = ", desc); }
    }
    ret;
}

type Account {
    owner: Text;
    balance: Int;
    transactions: Int;

    fn deposit(amount: Int) -> Void {
        self.balance = self.balance + amount;
        self.transactions = self.transactions + 1;
        ret;
    }

    fn withdraw(amount: Int) -> Bool {
        if amount > self.balance { ret false; }
        self.balance = self.balance - amount;
        self.transactions = self.transactions + 1;
        ret true;
    }

    fn summary() -> Text {
        let s: Text = self.owner + " | balance=" + int_to_text(self.balance) + " | txns=" + int_to_text(self.transactions);
        ret s;
    }
}

fn main() -> Void {
    let acc: Account = Account { owner: "Alice", balance: 1000, transactions: 0 };
    acc.deposit(500);
    let ok1: Bool = acc.withdraw(200);
    let ok2: Bool = acc.withdraw(5000);
    acc.deposit(300);
    let ok3: Bool = acc.withdraw(100);
    let report: Text = acc.summary();
    fx {
        println(report);
        println("withdraw  200: ", ok1);
        println("withdraw 5000: ", ok2);
        println("withdraw  100: ", ok3);
    }
    ret;
}

@pure
fn levelFor(salary: Int) -> Text {
    if salary >= 100000 { ret "senior"; }
    if salary >= 60000 { ret "mid"; }
    ret "junior";
}

type Payroll {
    total: Int;
    senior: Int;
    mid: Int;
    junior: Int;
    budget: Int;

    fn record(salary: Int, level: Text) -> Void {
        self.total = self.total + 1;
        self.budget = self.budget + salary;
        if level == "senior" { self.senior = self.senior + 1; ret; }
        if level == "mid" { self.mid = self.mid + 1; ret; }
        self.junior = self.junior + 1;
        ret;
    }
}

fn main() -> Void {
    if !has_toon() { fx { println("yyjson unavailable"); } ret; }

    let payload: Text = "{\"employees\":[{\"name\":\"Alice\",\"salary\":120000},{\"name\":\"Bob\",\"salary\":75000},{\"name\":\"Carol\",\"salary\":45000},{\"name\":\"Dave\",\"salary\":95000},{\"name\":\"Eve\",\"salary\":60000}]}";
    let doc: ToonDoc = toon_parse(payload);
    let root: ToonNode = toon_root(doc);
    let employees: ToonNode = toon_key(root, "employees");

    let payroll: Payroll = new Payroll();

    loop i in 0..toon_len(employees) {
        let emp: ToonNode = toon_at(employees, i);
        let name: Text = toon_get_text(emp, "name");
        let salary: Int = toon_get_int_or(emp, "salary", 0);
        let level: Text = levelFor(salary);
        payroll.record(salary, level);
        fx { println(name, " ($", salary, ") -> ", level); }
        toon_free(emp);
    }

    let avg: Real = payroll.budget * 1.0 / payroll.total;
    fx {
        println("---");
        println("Total employees: ", payroll.total);
        println("Senior: ", payroll.senior, " | Mid: ", payroll.mid, " | Junior: ", payroll.junior);
