@pure
fn insertion_sort(arr: Int[]) -> Int[] {
    let n: Int = length(arr);
    if n <= 1 { ret arr; }

    let result: Int[] = [];
    loop i in 0..n {
        let v: Int = arr[i];
        let j: Int = length(result);
        result = result + [v];

        loop while j > 0 && result[j - 1] > v {
            result[j] = result[j - 1];
            result[j - 1] = v;
            j = j - 1;
        }
    }

    ret result;
}

