fn prime_factors(n: Int) -> Int[] {
    let factors: Int[] = [];
    let divisor: Int = 2;
    let remaining: Int = n;
    loop remaining > 1 {
        if remaining % divisor == 0 {
            factors = factors + [divisor];
            remaining = remaining / divisor;
        } else {
            divisor = divisor + 1;
        }
    }
    ret factors;
}

