type Parser {
    input: Text;
    pos: Int;

    fn init(s: Text) -> Void {
        self.input = s;
        self.pos = 0;
        ret;
    }

    fn peek() -> Text {
        if self.pos >= string_len(self.input) { ret ""; }
        ret copy(self.input, self.pos + 1, 1);
    }

    fn consume() -> Text {
        let ch: Text = self.peek();
        self.pos = self.pos + 1;
        ret ch;
    }

    fn skip_whitespace() -> Void {
        loop self.peek() == " " { self.pos = self.pos + 1; }
        ret;
    }

    fn parse_number() -> Int {
        self.skip_whitespace();
        let result: Int = 0;
        loop self.peek() >= "0" && self.peek() <= "9" {
            let digit: Int = parse_int(self.consume());
            result = result * 10 + digit;
        }
        ret result;
    }

    fn parse_factor() -> Int {
        self.skip_whitespace();
        if self.peek() == "(" {
            self.consume();
            let val: Int = self.parse_expr();
            if self.peek() == ")" { self.consume(); }
            ret val;
        }
        ret self.parse_number();
    }

    fn parse_term() -> Int {
        let left: Int = self.parse_factor();
        self.skip_whitespace();
        loop self.peek() == "*" || self.peek() == "/" {
            let op: Text = self.consume();
            let right: Int = self.parse_factor();
            if op == "*" {
                left = left * right;
            } else {
                left = left / right;
            }
            self.skip_whitespace();
        }
        ret left;
    }

    fn parse_expr() -> Int {
        let left: Int = self.parse_term();
        self.skip_whitespace();
        loop self.peek() == "+" || self.peek() == "-" {
            let op: Text = self.consume();
            let right: Int = self.parse_term();
            if op == "+" {
                left = left + right;
            } else {
                left = left - right;
            }
            self.skip_whitespace();
        }
        ret left;
    }
}

fn main() -> Void {
    let p: Parser = new Parser {};
    p.init("3 + 5 * (10 - 4) / 2");
    fx { println("Result: ", p.parse_expr()); }
    ret;
}

type Perceptron {
    weights: Real[];
    bias: Real;
    lr: Real;

    fn init(n_inputs: Int) -> Void {
        self.weights = [];
        self.lr = 0.1;
        fx {
            randomize();
            loop i in 0..n_inputs { self.weights = self.weights + [random(100) / 100.0]; }
            self.bias = random(100) / 100.0;
        }
        ret;
    }

    fn activate(x: Real) -> Int {
        if x >= 0.0 { ret 1; }
        ret 0;
    }

    fn predict(inputs: Real[]) -> Int {
        let sum: Real = self.bias;
        loop i in 0..length(inputs) { sum = sum + inputs[i] * self.weights[i]; }
        ret self.activate(sum);
    }

    fn train(inputs: Real[], target: Int) -> Void {
        let prediction: Int = self.predict(inputs);
        let error: Int = target - prediction;
        loop i in 0..length(inputs) {
            self.weights[i] = self.weights[i] + self.lr * real(error) * inputs[i];
        }
        self.bias = self.bias + self.lr * real(error);
        ret;
    }
}

fn main() -> Void {
