}

type Board {
    size: Int;
    queens: Int[];

    fn init(n: Int) -> Void {
        self.size = n;
        self.queens = [];
        loop i in 0..n { self.queens = self.queens + [-1]; }
        ret;
    }

    fn is_safe(col: Int, row: Int) -> Bool {
        loop c in 0..col {
            let r: Int = self.queens[c];
            if r == row { ret false; }
            if r - c == row - col || r + c == row + col { ret false; }
        }
        ret true;
    }

    fn solve(col: Int) -> Bool {
        if col >= self.size { ret true; }
        loop row in 0..self.size {
            if self.is_safe(col, row) {
                self.queens[col] = row;
                if self.solve(col + 1) { ret true; }
                self.queens[col] = -1;
            }
        }
        ret false;
    }

    fn print_board() -> Void {
        loop r in 0..self.size {
            let line: Text = "";
            loop c in 0..self.size {
                if self.queens[c] == r {
                    line = line + "Q ";
                } else {
                    line = line + ". ";
                }
            }
            fx { println(line); }
        }
        ret;
    }
}

fn main() -> Void {
    let b: Board = new Board {};
    b.init(8);
    if b.solve(0) {
        b.print_board();
    } else {
        fx { println("No solution found."); }
    }
    ret;
}

type DFA {
    states: Int;
    transitions: Int[][];
    accepting: Bool[];
    current: Int;

    fn init() -> Void {
        self.states = 3;
        self.transitions = [[0, 1], [2, 0], [1, 2]];
        self.accepting = [true, false, false];
        self.current = 0;
        ret;
    }

    fn reset_dfa() -> Void {
        self.current = 0;
        ret;
    }

    fn step(input_symbol: Int) -> Void {
        self.current = self.transitions[self.current][input_symbol];
        ret;
    }

    fn is_accepting() -> Bool {
        ret self.accepting[self.current];
    }

    fn test(input_str: Text) -> Bool {
        self.reset_dfa();
        loop i in 0..string_len(input_str) {
            let symbol: Int = parse_int(copy(input_str, i + 1, 1));
            self.step(symbol);
        }
        ret self.is_accepting();
    }
}

