@pure
@pre n > 0
@post result >= 0
fn collatz_steps(n: Int) -> Int {
    let steps: Int = 0;
    let current: Int = n;
    loop current > 1 {
        if current % 2 == 0 {
            current = current / 2;
        } else {
            current = 3 * current + 1;
        }
        steps = steps + 1;
    }
    ret steps;
}

fn main() -> Void {
    let steps: Int = collatz_steps(12);
    fx { println("Collatz steps for 12: ", steps); }
    ret;
}

fn main() -> Void {
    const Limit: Int = 50;
    let primes: Bool[] = [];

    // Initialize sieve array with true
    loop i in 0..Limit + 1 { primes = primes + [true]; }

    // 0 and 1 are not prime
    if Limit >= 0 { primes[0] = false; }
    if Limit >= 1 { primes[1] = false; }

    // Sieve of Eratosthenes logic
    loop p in 2..Limit + 1 {
        if primes[p] {
            // p is prime, mark its multiples starting from p*p
            let multiple: Int = p * p;
            loop multiple <= Limit { primes[multiple] = false; multiple = multiple + p; }
        }
    }

    // Output the results
    fx {
        println("Primes up to ", Limit, ":");
        loop i in 0..Limit + 1 { if primes[i] { print(i, " "); } }
        println("");
    }

    ret;
}

@pre n >= 2
@post length(result) > 0
@pure
fn sieveOfEratosthenes(n: Int) -> Int[] {
    let isPrime: Bool[] = [];
    loop i in 0..n + 1 { isPrime = isPrime + [true]; }
    isPrime[0] = false;
    if n >= 1 { isPrime[1] = false; }

    loop p in 2..n + 1 {
        if isPrime[p] {
            let square: Int = p * p;
            if square <= n {
                loop multiple in square..n + 1 { isPrime[multiple] = false; }
            }
        }
    }

    let primes: Int[] = [];
    loop i in 0..n + 1 { if isPrime[i] { primes = primes + [i]; } }
    ret primes;
}

fn main() -> Void {
    let limit: Int = 50;
    let primes: Int[] = sieveOfEratosthenes(limit);
    fx {
        println("Primes up to ", limit, ": ");
        loop i in 0..length(primes) { print(primes[i], " "); }
        println("");
        println("Count: ", length(primes));
    }
    ret;
}

type InventoryItem {
