type Stats {
    seen: Int = 0;
    total: Real = 0.0;
    minValue: Real = 0.0;
    maxValue: Real = 0.0;
    initialized: Bool = false;

    fn observe(value: Real) -> Void {
        if !self.initialized {
            self.minValue = value;
            self.maxValue = value;
            self.initialized = true;
        } else {
            if value < self.minValue { self.minValue = value; }
            if value > self.maxValue { self.maxValue = value; }
        }
        self.seen = self.seen + 1;
        self.total = self.total + value;
        ret;
    }

    fn mean() -> Real {
        if self.seen == 0 { ret 0.0; }
        ret self.total / self.seen;
    }
}

